    private fun maple(cv: Canvas, x: Float, y: Float, s: Float) {
        p.reset()
        for (k in 0 until 10) { val a = -Math.PI / 2 + k * Math.PI / 5; val rad = if (k % 2 == 0) s else s * 0.45f; val px = x + (Math.cos(a) * rad).toFloat(); val py = y + (Math.sin(a) * rad).toFloat(); if (k == 0) p.moveTo(px, py) else p.lineTo(px, py) }
        p.close(); sh(cv, p, 0xFFE0442B, 0.035f); ln(cv, x, y, x, y + s * 1.1f, 0xFF8A3A1A, 0.035f)
    }

    private fun seagull(cv: Canvas) {
        sea(cv, 0.45f)
        p.reset(); p.moveTo(-0.9f, -0.45f); p.quadTo(-0.55f, -0.8f, -0.1f, -0.15f); p.quadTo(-0.5f, -0.3f, -0.9f, -0.45f); p.close(); sh(cv, p, 0xFFB8C2D4)
        p.reset(); p.moveTo(0.9f, -0.6f); p.quadTo(0.5f, -0.85f, 0.15f, -0.15f); p.quadTo(0.5f, -0.4f, 0.9f, -0.6f); p.close(); sh(cv, p, 0xFFB8C2D4)
        ov(cv, -0.45f, -0.3f, 0.4f, 0.1f, 0xFFFFFFFF)
        ci(cv, 0.42f, -0.22f, 0.17f, 0xFFFFFFFF); poly(0.56f, -0.24f, 0.8f, -0.18f, 0.56f, -0.14f); sh(cv, p, 0xFFF2B33D, 0.03f); dot(cv, 0.46f, -0.26f, 0.035f, INK)
